import{_ as e}from"./chunks/settings-robot.pc.en.95Z7NI6l.js";import{_ as o,o as a,c as s,a5 as r}from"./chunks/framework.BjM_ivYE.js";const m=JSON.parse('{"title":"Payload configuration","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/payload_setting.md","filePath":"manual/troubleshooting/payload_setting.md","lastUpdated":1790646309000}'),n={name:"manual/troubleshooting/payload_setting.md"};function d(i,t,l,h,c,u){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="payload-configuration" tabindex="-1">Payload configuration <a class="header-anchor" href="#payload-configuration" aria-label="Permalink to &quot;Payload configuration&quot;">​</a></h1><p>Anything you mount on the robot shifts its center of mass, and the walk gets unsteady. Register the <strong>mass and center of mass</strong> of the load in <code>Payload Configuration</code> under <strong>Robot settings › Payload setup</strong>, and the walking dynamics account for it.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>Enter an <strong>approximate mass and center-of-mass height (Z)</strong> even when you do not know the exact figures. A rough value visibly steadies the walk, and <strong>leaving it empty is the worst case</strong>.</p></div></div><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Put the robot on flat, stable ground.</li><li>The app must be connected to the robot — without a connection it cannot read the slots.</li><li>Know the load&#39;s mass and where its center of mass sits (X/Y/Z) relative to the robot body.</li></ul><h2 id="what-is-on-the-screen" tabindex="-1">What is on the screen <a class="header-anchor" href="#what-is-on-the-screen" aria-label="Permalink to &quot;What is on the screen&quot;">​</a></h2><p><img src="'+e+'" alt="Robot parameters — Payload Configuration"></p><p>Wide screens show two columns; narrow ones stack them.</p><table tabindex="0"><thead><tr><th>Area</th><th>Contents</th></tr></thead><tbody><tr><td>Top left</td><td><strong>3D preview</strong> — registered payloads appear as markers. Tap a marker to select that slot; drag the X/Y/Z arrows to move it</td></tr><tr><td>Bottom left</td><td><strong>Editor for the selected slot</strong> — <code>Mass</code>, <code>X</code>, <code>Y</code>, <code>Z</code>. With nothing selected it edits the first slot</td></tr><tr><td>Top right</td><td><strong>Slot table</strong> — the slots the robot reports. <code>●</code> is a fixed payload, <code>◻</code> a user slot</td></tr><tr><td>Bottom right</td><td><strong>Total</strong>, plus the <code>Get</code> and <code>Set Payload</code> buttons</td></tr></tbody></table><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h2><ol><li><strong>Pick a slot.</strong> Tap the slot you want in the table on the right. Ticking its checkbox marks it as <strong>mounted</strong> and fills in the catalogue defaults the robot holds for it.</li><li><strong>Enter the values.</strong> In the editor on the left, set <code>Mass</code> (kg) and <code>X</code>, <code>Y</code>, <code>Z</code> (m). Tap a field to type a number, or use <code>−</code> and <code>+</code>. The <strong>Interval</strong> chips at the top right of the editor (<code>0.001</code>, <code>0.01</code>, <code>0.1</code>, <code>1</code>) set how much each press moves the value.</li><li><strong>Check the total.</strong> The total box below the editor shows the combined mass and center of mass. If the total goes over the limit it turns red and <code>Set Payload</code> is disabled.</li><li><strong>Press <code>Set Payload</code></strong>, then confirm with <strong><code>Apply</code></strong>. The confirmation repeats the number of mounted slots and the totals. <strong>Unticked slots are sent with mass 0, which clears them.</strong></li><li>Once applied the app re-reads the robot and shows <em>Applied (re-confirmed with robot values)</em>. The new values reach the walking dynamics immediately and are ramped in over one to two seconds.</li></ol><p><code>Get</code> re-reads the slots stored on the robot — <strong>any edits in progress are discarded.</strong></p><h2 id="allowed-ranges" tabindex="-1">Allowed ranges <a class="header-anchor" href="#allowed-ranges" aria-label="Permalink to &quot;Allowed ranges&quot;">​</a></h2><p>The bottom line of the editor always shows the range the connected robot allows. Robots whose software does not report its limits fall back to the values below.</p><table tabindex="0"><thead><tr><th>Item</th><th>Range</th></tr></thead><tbody><tr><td>Mass per slot</td><td>0 – 20 kg</td></tr><tr><td>Total</td><td>20 kg or less</td></tr><tr><td>Center of mass</td><td>|X| ≤ 0.5 m, |Y| ≤ 0.3 m, |Z| ≤ 0.4 m</td></tr></tbody></table><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>After changing mass or center of mass, <strong>run the center-of-mass (ZMP) calibration again</strong>. The calibration is stored against the load that was on the robot at the time, so an earlier calibration no longer fits once the load changes. It lives under <strong>Robot settings › Calibration</strong>.</p></div></div><h2 id="when-it-does-not-work" tabindex="-1">When it does not work <a class="header-anchor" href="#when-it-does-not-work" aria-label="Permalink to &quot;When it does not work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message on screen</th><th>What it means and what to do</th></tr></thead><tbody><tr><td><em>Read failed — check robot connection</em></td><td>There is no connection to the robot. Check <a href="/RBQ/manual/gui/connection.html">Connection</a></td></tr><tr><td><em>Legacy robot — 13 slots unsupported</em></td><td>The robot software predates the slot API. Run a <a href="/RBQ/manual/gui/software-update.html">robot software update</a> and try again</td></tr><tr><td><em>Total exceeds the 20 kg limit</em></td><td>Remove a slot or lower a mass. Nothing is sent while the total is over</td></tr><tr><td><em>Apply failed — out of range or disconnected</em></td><td>A value is outside the ranges above, or the connection dropped mid-send</td></tr></tbody></table><p>Some robots already account for their fixed equipment in the robot-side configuration and therefore expose <strong>only one user slot</strong>. A slot count that differs from what you expect is normal — use it as is.</p><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck {#still-stuck}&quot;">​</a></h2><p>Tell us which slots you filled in with what, the total you had, and the message shown on screen.</p><p><strong>→ <a href="/RBQ/manual/support/">Support</a></strong></p>',22)])])}const b=o(n,[["render",d]]);export{m as __pageData,b as default};
